// Extract message data from WhatsApp Cloud API webhook payload.
// Meta also sends status updates for outbound messages; those are not user messages.
const body = $input.first().json.body;

if (!body?.entry?.length) {
  console.log('[Meta Webhook] Empty or invalid payload; skipping.');
  return [];
}

const value = body.entry[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!message) {
  const status = value?.statuses?.[0];
  console.log('[Meta Webhook] Status update, no message to process:', status?.status ?? 'unknown');
  return [];
}

const messageType = message.type;

return [{
  json: {
    senderPhone: message.from,
    messageId: message.id,
    messageType,
    timestamp: new Date(parseInt(message.timestamp, 10) * 1000).toISOString(),
    textContent: message.text?.body ?? null,
    mediaId: message.audio?.id ?? message.image?.id ?? message.document?.id ?? null,
    mediaMimeType: message.audio?.mime_type ?? message.image?.mime_type ?? null,
    senderName: contact?.profile?.name ?? null,
    waPhoneId: value?.metadata?.phone_number_id ?? null,
    rawPayload: JSON.stringify(body),
    _skip: false,
  }
}];

